#!/usr/bin/env bash
# Generates, from every schema in contracts/, TypeScript types in worker/src/contracts/ and
# Pydantic v2 models in node/src/yt_digest_node/contracts/.
#   ./scripts/contracts.sh          regenerate the committed files
#   ./scripts/contracts.sh --check  regenerate into a temporary directory and exit 1, naming the
#                                   files, when a committed generated file differs
# CONTRACTS_ROOT (default: the repository root) is the tree holding contracts/ and the generated
# files; the generators always come from this repository's node/ and worker/ dependencies.
set -euo pipefail
repo="$(cd "$(dirname "$0")/.." && pwd)"
root="$(cd "${CONTRACTS_ROOT:-$repo}" && pwd)"
ts_dir=worker/src/contracts
py_dir=node/src/yt_digest_node/contracts

py() { uv run --quiet --locked --directory "$repo/node" "$@"; }

# Writes every generated file under the directory $1, a fresh temporary directory, so that the
# output does not depend on where it lands.
generate() {
  local out="$1" schema name header
  mkdir -p "$out/$ts_dir" "$out/$py_dir"
  printf '# Generated by scripts/contracts.sh: do not edit.\n"""Models generated from contracts/."""\n' \
    >"$out/$py_dir/__init__.py"
  for schema in "$root"/contracts/*.schema.json; do
    name="$(basename "$schema" .schema.json)"
    header="Generated by scripts/contracts.sh from contracts/$name.schema.json: do not edit."
    "$repo/worker/node_modules/.bin/json2ts" --input "$schema" --output "$out/$ts_dir/$name.ts" \
      --bannerComment "// $header"
    py datamodel-codegen --input "$schema" --input-file-type jsonschema \
      --output-model-type pydantic_v2.BaseModel --target-python-version 3.12 \
      --use-specialized-enum --use-standard-collections --use-union-operator --use-double-quotes \
      --use-title-as-name --use-annotated --disable-timestamp --formatters builtin \
      --custom-file-header "# $header" --output "$out/$py_dir/${name//-/_}.py"
  done
  py ruff check --quiet --fix-only --config "$repo/node/pyproject.toml" "$out/$py_dir"
  py ruff format --quiet --config "$repo/node/pyproject.toml" "$out/$py_dir"
}

tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT

case "${1:-}" in
  "")
    generate "$tmp"
    for dir in "$ts_dir" "$py_dir"; do
      rm -rf "${root:?}/$dir"
      mkdir -p "$(dirname "$root/$dir")"
      cp -R "$tmp/$dir" "$root/$dir"
    done
    ;;
  --check)
    generate "$tmp"
    stale=()
    while IFS= read -r file; do
      if ! cmp -s "$tmp/$file" "$root/$file"; then stale+=("$file"); fi
    done < <(cd "$tmp" && find "$ts_dir" "$py_dir" -type f -not -path '*/__pycache__/*' | sort;
             cd "$root" && find "$ts_dir" "$py_dir" -type f -not -path '*/__pycache__/*' 2>/dev/null | sort)
    if ((${#stale[@]} > 0)); then
      echo "generated files are stale; run ./scripts/contracts.sh:" >&2
      printf '%s\n' "${stale[@]}" | sort -u | sed 's/^/  /' >&2
      exit 1
    fi
    echo "generated files are up to date"
    ;;
  *) echo "usage: $0 [--check]" >&2; exit 2 ;;
esac
